import React from 'react';
import {Link} from 'react-router-dom';
// import {VscMenu, AiOutlineClose} from 'react-icons/all'
import logo from "../../../img/favicon.ico";
import './Navbar.css'
import '../../Button.css';
import {Button} from "../../Button";
import Popup from "../../Popup/Popup";

function Navbar() {



    const [isOpenLoginForm, setOpenLoginForm] = React.useState(false);

    const handleOpenLoginForm = () => {
        setOpenLoginForm(!isOpenLoginForm);
    }



       return (
        <>
            <div className="navbar">
                <Link to='/' className="navbar-title">
                    <img src={logo} className={'logo'} alt={logo}/>
                    <div className={'title'}>UniAdvisor.it</div>
                </Link>
                <div className="menu-content">
                    <Button buttonStyle='btn--outline' onClick={handleOpenLoginForm}>ACCEDI/REGISTRATI</Button>
                    {isOpenLoginForm && <Popup
                        title={<>
                        <h1>Il sito è in fase di manutenzione</h1>
                        <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit, sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. Ut enim ad minim veniam, quis nostrud exercitation ullamco laboris nisi ut aliquip ex ea commodo consequat. Duis aute irure dolor in reprehenderit in voluptate velit esse cillum dolore eu fugiat nulla pariatur. Excepteur sint occaecat cupidatat non proident, sunt in culpa qui officia deserunt mollit anim id est laborum.</p>
                        <button>Test button</button>
                    </>}
                        handleOpenLoginForm={handleOpenLoginForm}
                    />}
                </div>
            </div>
        </>
    )
        ;
}

export default Navbar;
